return ['domain'=>'zinn-reseller','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ne_NP','project-id-version'=>'zinn-reseller','pot-creation-date'=>'2026-10-01T20:50:13+00:00','po-revision-date'=>'2026-10-01T20:50:13+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Reseller Toolkit'=>'Zinn® Reseller Toolkit','https://zinndigital.com/wordpress-plugins/zinn-reseller'=>'https://zinndigital.com/wordpress-plugins/zinn-reseller','Sell Zinn Digital® hosting from your own WordPress site — WordPress, WooCommerce, agency, reseller, cloud and VPS hosting. Search and offer domains from your reseller account, sign your clients straight into their hosting panel, and provision hosting automatically when a WooCommerce order is paid.'=>'आफ्नै WordPress साइटबाट Zinn Digital® होस्टिङ बेच्नुहोस् — WordPress, WooCommerce, एजेन्सी, रिसेलर, क्लाउड र VPS होस्टिङ। आफ्नो रिसेलर खाताबाट डोमेनहरू खोज्नुहोस् र प्रस्ताव गर्नुहोस्, आफ्ना ग्राहकहरूलाई सिधै उनीहरूको होस्टिङ प्यानलमा साइन इन गराउनुहोस्, र WooCommerce अर्डरको भुक्तानी भएपछि स्वचालित रूपमा होस्टिङ उपलब्ध गराउनुहोस्।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','The hosting platform answered with status %d.'=>'होस्टिङ प्लेटफर्मले %d स्टाटस सहित जवाफ दियो।','Find your domain name'=>'तपाईंको डोमेन नाम खोज्नुहोस्','Search'=>'खोज्नुहोस्','No extensions were checked for that name.'=>'त्यस नामका लागि कुनै पनि विस्तारहरू जाँच गरिएनन्।','Domain search is unavailable on this site at the moment.'=>'यस साइटमा हाल डोमेन खोज उपलब्ध छैन।','We could not reach the domain registry just now. Please try again in a moment.'=>'हामीले भर्खरै डोमेन रजिस्ट्रीसँग सम्पर्क गर्न सकेनौं। कृपया केही बेरपछि पुन: प्रयास गर्नुहोस्।','The API key is missing or no longer valid. Check it under Zinn Digital® → Reseller Toolkit.'=>'API कुञ्जी हराइरहेको छ वा अब मान्य छैन। यसलाई Zinn Digital® → Reseller Toolkit अन्तर्गत जाँच गर्नुहोस्।','This API key does not carry the sites.view permission, which the domain search needs. Add it to the key in your reseller panel, or clear the key here to fall back to the public search.'=>'यो API key मा sites.view अनुमति छैन, जुन डोमेन खोजीलाई आवश्यक पर्दछ। यसलाई तपाईंको रिसेलर प्यानलमा रहेको key मा थप्नुहोस्, वा सार्वजनिक खोजीमा फर्कन यहाँ भएको key खाली गर्नुहोस्।','Only administrators see this:'=>'व्यवस्थापकहरूले मात्र यो देख्छन्:','We could not check this one — try again'=>'हामीले यो जाँच गर्न सकेनौं — कृपया पुन: प्रयास गर्नुहोस्','Already registered'=>'पहिले नै दर्ता भइसकेको','Available — ask us for a price'=>'उपलब्ध छ — हामीलाई मूल्य सोध्नुहोस्','Available — %1$s %2$s for the first year'=>'उपलब्ध छ — पहिलो वर्षको लागि %1$s %2$s','Register it'=>'दर्ता गर्नुहोस्','Manage my hosting'=>'मेरो होस्टिङ व्यवस्थापन गर्नुहोस्','Please sign in first.'=>'कृपया पहिले साइन इन गर्नुहोस्।','This account is not linked to a hosting service yet.'=>'यो खाता अझै कुनै पनि होस्टिङ सेवासँग जोडिएको छैन।','The hosting platform did not return a sign-in link.'=>'होस्टिङ प्लेटफर्मले साइन-इन लिङ्क फिर्ता पठाएन।','Reseller Toolkit'=>'पुनर्विक्रेता टुलकिट','Account'=>'खाता','Features'=>'सुविधाहरू','Styling'=>'शैलीकरण','AI agents (MCP)'=>'एआई एजेन्टहरू (MCP)','Allow AI agents (MCP)'=>'AI एजेन्टहरू (MCP) लाई अनुमति दिनुहोस्','Off: the tools below and their REST routes are not registered at all.'=>'बन्द: तलका उपकरणहरू र तिनीहरूका REST मार्गहरू पटक्कै दर्ता गरिएका छैनन्।','Your Zinn Digital® reseller account'=>'तपाईंको Zinn Digital® रिसेलर खाता','Create a reseller API key in your Zinn® dashboard under Developer → API keys, and paste it here.'=>'तपाईंको Zinn® ड्यासबोर्डमा विकासकर्ता → API कुञ्जीहरू अन्तर्गत रिसेलर API कुञ्जी सिर्जना गर्नुहोस्, र यसलाई यहाँ टाँस्नुहोस्।','Reseller API key'=>'पुनर्विक्रेता API कुञ्जी','Held on this site only, and never included in an export or a diagnostics report.'=>'यस साइटमा मात्र राखिएको छ, र कहिल्यै पनि निर्यात वा निदान प्रतिवेदनमा समावेश गरिएको छैन।','Plan to provision'=>'प्रबन्ध गर्नुपर्ने योजना','The plan code new customers are put on. Leave blank to be asked each time.'=>'नयाँ ग्राहकहरूलाई राखिने योजना कोड। प्रत्येक पटक सोधिनका लागि खाली छोड्नुहोस्।','API address'=>'API ठेगाना','Leave this alone unless Zinn® support has asked you to change it.'=>'Zinn® समर्थनले तपाईंलाई यसलाई परिवर्तन गर्न नभनेसम्म यसलाई यस्तै छोड्नुहोस्।','Control-panel address'=>'नियन्त्रण-प्यानल ठेगाना','Where the “My hosting” link sends your customers.'=>'"मेरो होस्टिङ" लिङ्कले तपाईंका ग्राहकहरूलाई पठाउने ठाउँ।','Domain search'=>'डोमेन खोज','Provide the [zinn_domain_search] shortcode'=>'[zinn_domain_search] सर्टकोड उपलब्ध गराउनुहोस्','Put the shortcode on any page to let visitors check a domain and buy it through you.'=>'आगन्तुकहरूलाई डोमेन जाँच गर्न र तपाईंमार्फत खरिद गर्न अनुमति दिन कुनै पनि पृष्ठमा सर्टकोड राख्नुहोस्।','Panel link'=>'प्यानल लिङ्क','Show a “My hosting” link to signed-in customers'=>'साइन-इन गरेका ग्राहकहरूलाई "मेरो होस्टिङ" लिङ्क देखाउनुहोस्','WooCommerce provisioning'=>'WooCommerce प्रोभिजनिङ','Provision hosting automatically when a WooCommerce order completes'=>'WooCommerce अर्डर पूरा भएपछि स्वचालित रूपमा होस्टिङको व्यवस्था गर्नुहोस्','Only takes effect on orders containing a product you have mapped to a Zinn® plan.'=>'तपाईंले Zinn® योजनामा म्याप गर्नुभएको उत्पादन समावेश भएका अर्डरहरूमा मात्र लागू हुन्छ।','Domain search appearance'=>'डोमेन खोज उपस्थिति','This widget renders inside your own theme. Pick a preset, or set your own colours — either way nothing is added to your pages that a visitor can see as ours.'=>'यो विजेट तपाईंको आफ्नै थिम भित्र देखिन्छ। प्रिसेट छान्नुहोस्, वा आफ्नै रङहरू सेट गर्नुहोस् — जुनसुकै तरिका अपनाए पनि आगन्तुकले हाम्रो हो भनी देख्न सक्ने केही पनि तपाईंका पृष्ठहरूमा थपिँदैन।','Every class the widget uses is listed in the plugin’s readme, so a developer can override anything a preset does not cover.'=>'विजेटले प्रयोग गर्ने प्रत्येक क्लास प्लगइनको readme मा सूचीबद्ध गरिएको छ, ताकि प्रिसेटले नसमेटेको कुनै पनि कुरालाई विकासकर्ताले ओभरराइड गर्न सकून्।','Follow my theme'=>'मेरो विषयवस्तु पछ्याउनुहोस्','Soft'=>'नरम','High contrast'=>'उच्च कन्ट्रास्ट','Compact'=>'कम्प्याक्ट','Buy-link colour'=>'खरिद लिङ्कको रङ','“Available” colour'=>'"उपलब्ध" रङ','“Could not check” colour'=>'“जाँच गर्न सकिएन” रङ','Error colour'=>'त्रुटि रङ','Corner rounding'=>'कुना गोलाकार','Space inside each row'=>'प्रत्येक पङ्क्तिको भित्रको खाली ठाउँ','Text size'=>'पाठको आकार','Domain-name weight'=>'डोमेन नामको वजन','No reseller API key yet.'=>'अहिलेसम्म कुनै पुनर्विक्रेता API कुञ्जी छैन।','Domain search already works without one, at the public prices. The panel link and WooCommerce provisioning need a key: create one in your Zinn® dashboard under Developer → API keys.'=>'डोमेन खोजी सार्वजनिक मूल्यहरूमा यस बिना नै पहिलेदेखि काम गर्दछ। प्यानल लिङ्क र WooCommerce प्रावधानका लागि एउटा कुञ्जी चाहिन्छ: तपाईंको Zinn® ड्यासबोर्डमा Developer → API keys अन्तर्गत एउटा सिर्जना गर्नुहोस्।','Open my Zinn® dashboard'=>'मेरो Zinn® ड्यासबोर्ड खोल्नुहोस्','A key is set, but nothing is switched on.'=>'कुञ्जी सेट गरिएको छ, तर केही पनि अन गरिएको छैन।','None of the three features is enabled, so this plugin is doing nothing on your site. Turn on what you need under Features.'=>'तीन सुविधाहरू मध्ये कुनै पनि सक्षम गरिएको छैन, त्यसैले यो प्लगइनले तपाईंको साइटमा केही गरिरहेको छैन। सुविधाहरू अन्तर्गत आफूलाई चाहिने कुराहरू अन गर्नुहोस्।','Open Features'=>'सुविधाहरू खोल्नुहोस्','Ready — %d feature switched on.'=>'तयार — %d सुविधा सक्रिय गरियो।' . "\0" . 'तयार — %d सुविधाहरू सक्रिय गरियो।','Selling from'=>'बिक्री स्रोत','Settings'=>'सेटिङहरू','No API key yet, so nothing is connected.'=>'अहिलेसम्म कुनै API कुञ्जी छैन, त्यसैले केही पनि जडान गरिएको छैन।','Not connected: %s'=>'जडान भएको छैन: %s','Connected. Your reseller programme is %s.'=>'जडान भयो। तपाईंको रिसेलर कार्यक्रम %s हो।','No Zinn® API key is configured, so nothing was provisioned.'=>'कुनै Zinn® API कुञ्जी कन्फिगर गरिएको छैन, त्यसैले केही पनि प्रावधान गरिएको थिएन।','This order did not include a domain name, so there was nothing to provision.'=>'यो अर्डरमा डोमेन नाम समावेश थिएन, त्यसैले व्यवस्था गर्नुपर्ने केही थिएन।','The hosting platform did not return a site.'=>'होस्टिङ प्लेटफर्मले कुनै साइट फिर्ता गरेन।','Zinn® hosting provisioned for %1$s (service %2$s).'=>'%1$s का लागि Zinn® होस्टिङको व्यवस्था गरियो (सेवा %2$s)।','The hosting platform did not return a client account.'=>'होस्टिङ प्लेटफर्मले क्लाइन्ट खाता फिर्ता गरेन।','Zinn® hosting was NOT provisioned: %s'=>'Zinn® होस्टिङको व्यवस्था गरिएन: %s','Zinn® product line'=>'Zinn® उत्पादन लाइन','The Zinn® product line to provision when this product is bought. Leave blank to use the default from the plugin settings.'=>'यो उत्पादन खरिद गर्दा उपलब्ध गराइने Zinn® उत्पादन लाइन। प्लगइन सेटिङहरूबाट पूर्वनिर्धारित मान प्रयोग गर्न खाली छोड्नुहोस्।','Zinn® hosting'=>'Zinn® होस्टिङ','Service id'=>'सेवा आईडी','Nothing provisioned for this order.'=>'यो अर्डरको लागि केही पनि व्यवस्था गरिएको छैन।','Stored. Type a new value to replace it.'=>'सङ्कलन गरियो। यसलाई बदल्न नयाँ मान टाइप गर्नुहोस्।','Filter this list…'=>'यो सूची फिल्टर गर्नुहोस्…','Filter this list'=>'यो सूची फिल्टर गर्नुहोस्','Nothing matches that filter.'=>'त्यो फिल्टरसँग केही पनि मेल खाँदैन।','Add a row'=>'पङ्क्ति थप्नुहोस्','Remove this row'=>'यो पङ्क्ति हटाउनुहोस्','Remove'=>'हटाउनुहोस्','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — अवलोकन','Overview'=>'सिंहावलोकन','Copied'=>'प्रतिलिपि गरियो','Every Zinn® plugin on this site, and whether it is working.'=>'यस साइटमा भएका प्रत्येक Zinn® प्लगइन, र यो काम गरिरहेको छ वा छैन।','No connection is needed for this plugin.'=>'यस प्लगइनका लागि कुनै जडान आवश्यक पर्दैन।','Open settings'=>'सेटिङहरू खोल्नुहोस्','You do not have permission to change these settings.'=>'तपाईंसँग यी सेटिङहरू परिवर्तन गर्ने अनुमति छैन।','Settings sections'=>'सेटिङ खण्डहरू','Support'=>'सहयोग','Save changes'=>'परिवर्तनहरू बचत गर्नुहोस्','Tools'=>'उपकरणहरू','Export settings'=>'सेटिङहरू निर्यात गर्नुहोस्','Reset to defaults'=>'पूर्वनिर्धारितमा रिसेट गर्नुहोस्','This puts every setting on this plugin back to its default. Continue?'=>'यसले यो प्लगइनको प्रत्येक सेटिङलाई पूर्वनिर्धारित अवस्थामा फर्काउनेछ। के तपाईं जारी राख्न चाहनुहुन्छ?','Diagnostics for support'=>'सहयोगका लागि निदान','Import a settings file'=>'सेटिङ फाइल आयात गर्नुहोस्','Import'=>'आयात गर्नुहोस्','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'निर्यात गरिएका फाइलहरूमा कहिल्यै पनि पासवर्ड, टोकन वा API कुञ्जीहरू हुँदैनन् — तपाईंले नयाँ साइटमा ती फेरि प्रविष्ट गर्नुपर्नेछ।','Settings saved.'=>'सेटिङहरू सुरक्षित गरियो।','Every setting on this plugin is back to its default.'=>'यस प्लगइनको प्रत्येक सेटिङ यसको पूर्वनिर्धारितमा फर्किएको छ।','Done.'=>'सम्पन्न भयो।','That action is not available.'=>'त्यो कार्य उपलब्ध छैन।','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'त्यो फाइल पढ्न सकिएन। Zinn® प्लगइनबाट निर्यात गरिएको सेटिङ फाइल छान्नुहोस्।','That file is too large to be a settings export.'=>'त्यो फाइल सेटिङ निर्यात हुन धेरै ठूलो छ।','That file is not a Zinn® settings export.'=>'त्यो फाइल Zinn® सेटिङ निर्यात होइन।','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'त्यो फाइल फरक प्लगइन (%s) बाट निर्यात गरिएको थियो, त्यसैले यसलाई यहाँ आयात गर्दा यो प्लगइनले नबुझ्ने सेटिङहरू भण्डारण हुनेछ।','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d सेटिङ आयात गरियो। पासवर्ड र API कुञ्जीहरू कहिल्यै पनि निर्यातमा समावेश हुँदैनन्, त्यसैले कृपया ती फेरि प्रविष्ट गर्नुहोस्।' . "\0" . '%d सेटिङहरू आयात गरियो। पासवर्ड र API कुञ्जीहरू कहिल्यै पनि निर्यातमा समावेश हुँदैनन्, त्यसैले कृपया ती फेरि प्रविष्ट गर्नुहोस्।','Connected'=>'जडान गरियो','Connecting…'=>'जडान हुँदैछ…','Connected, but something needs attention'=>'जडान भयो, तर केही कुरामा ध्यान दिन आवश्यक छ','Not connected'=>'जडान भएको छैन','Running on your own account'=>'तपाईंको आफ्नै खातामा चल्दैछ','We could not check this'=>'हामीले यो जाँच गर्न सकेनौँ','This plugin did not say why. Send a diagnostics report and we will look.'=>'यो प्लगइनले कारण खुलाएन। एउटा निदान प्रतिवेदन पठाउनुहोस् र हामी हेर्नेछौँ।','Connection status'=>'जडान स्थिति','Last checked %s ago.'=>'अन्तिम पटक %s अघि जाँच गरिएको।','(opens in a new tab)'=>'(नयाँ ट्याबमा खुल्छ)','Send this to Zinn® support'=>'यसलाई Zinn® समर्थनमा पठाउनुहोस्','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'ठ्याक्कै यही पठाइनेछ — अरू केही पनि होइन, र केही पनि लुकाइएको छैन। तपाईंका पासवर्डहरू, टोकनहरू र API कुञ्जीहरू यसमा छैनन्।','The diagnostics report that will be sent'=>'पठाइने निदान प्रतिवेदन','Copy to clipboard'=>'क्लिपबोर्डमा प्रतिलिपि गर्नुहोस्','Send this report to Zinn® support'=>'यो प्रतिवेदन Zinn® सहयोगलाई पठाउनुहोस्','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'हामी तपाईंको लागि समर्थन टिकट खोल्छौं र इमेल मार्फत जवाफ दिन्छौं। यदि तपाईं यसलाई पठाउन चाहनुहुन्न भने, यसलाई माथि प्रतिलिपि गर्नुहोस् र आफैंले टिकटमा टाँस्नुहोस्।','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'हामी यस सर्भर (%s) बाट Zinn Digital® सम्म पुग्न सकेनौं। माथिको रिपोर्ट प्रतिलिपि गर्नुहोस् र यसको सट्टा टिकट खोल्नुहोस् — तपाईंको सेटिङहरूमा केही पनि गलत छैन।','Sent. Zinn® support has your report and will reply by email.'=>'पठाइयो। Zinn® समर्थनले तपाईंको रिपोर्ट प्राप्त गरेको छ र इमेलमार्फत जवाफ दिनेछ।','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'पठाइयो। Zinn® समर्थनले तपाईंको रिपोर्ट प्राप्त गरेको छ — सन्दर्भ %s — र इमेलमार्फत जवाफ दिनेछ।','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'तपाईंले छोटो समयमा धेरै रिपोर्टहरू पठाउनुभएको छ। केही मिनेट पर्खनुहोस् र पुन: प्रयास गर्नुहोस् — अघिल्ला रिपोर्टहरू प्राप्त भइसकेका छन्।','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® ले भर्खरै रिपोर्ट स्वीकार गर्न सकेन — यो हाम्रो तर्फको समस्या हो, तपाईंको होइन। केही समयपछि पुन: प्रयास गर्नुहोस्, वा माथिको रिपोर्टलाई टिकटमा प्रतिलिपि गर्नुहोस्।','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'प्रतिवेदन अस्वीकृत गरियो (HTTP %d)। यसलाई माथि प्रतिलिपि गर्नुहोस् र त्यो नम्बर उल्लेख गरी टिकट खोल्नुहोस्।','%s — guides and services'=>'%s — मार्गदर्शिका र सेवाहरू','User guides'=>'प्रयोगकर्ता गाइडहरू','Read the %s user guide'=>'%s प्रयोगकर्ता गाइड पढ्नुहोस्','Hide this'=>'यो लुकाउनुहोस्','Zinn® hosting for WordPress'=>'WordPress का लागि Zinn® होस्टिङ','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, दैनिक ब्याकअप, निःशुल्क माइग्रेसन र एकभन्दा बढी साइट सञ्चालन गर्ने व्यक्तिहरूका लागि बनाइएको नियन्त्रण प्यानल।','The Zinn® marketplace'=>'Zinn® बजार','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'दुवै पक्ष सन्तुष्ट नभएसम्म रकम सुरक्षित रूपमा राखेर स्थापित साइटहरू, डोमेनहरू र लिङ्क प्लेसमेन्टहरू खरिद तथा बिक्री गर्नुहोस्।','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — यसलाई नै जीविकोपार्जनको पेशा बनाएका मानिसहरूलाई काममा लगाउनुहोस्','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'हाम्रो विश्वव्यापी फ्रिलान्स बजार: लेखक, डिजाइनर, विकासकर्ता र SEO विशेषज्ञहरूबाट १०,००० भन्दा बढी तयार सेवाहरू ब्राउज गर्नुहोस्, वा परियोजना पोस्ट गरेर तिनीहरूलाई बोलपत्र पेश गर्न दिनुहोस्।','Style preset'=>'शैली प्रिसेट','A starting point. Anything below overrides it.'=>'एक सुरूवाती विन्दु। तलको कुनै पनि कुराले यसलाई अधिरोहित गर्दछ।','Use my own colours and sizes'=>'मेरो आफ्नै रङहरू र आकारहरू प्रयोग गर्नुहोस्','Leave this off and the preset is used exactly as it is.'=>'यसलाई बन्द नै छोड्नुहोस् र पूर्वसेटलाई जस्ताको तस्तै प्रयोग गरिनेछ।','See the Zinn Digital® release notes.'=>'Zinn Digital® विमोचन टिप्पणीहरू हेर्नुहोस्।','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Zinn® अद्यावधिक सेवाले यो अद्यावधिकको लागि डाउनलोड लिङ्क जारी गरेन। यो साइटले Zinn® प्लेटफर्ममा पहुँच गर्न सक्छ भनी जाँच गर्नुहोस्, त्यसपछि फेरि प्रयास गर्नुहोस्।','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Zinn® अद्यावधिक सेवा (%s) बाट अद्यावधिक डाउनलोड गर्न सकिएन। केही मिनेटमा पुन: प्रयास गर्नुहोस्।','The downloaded update failed its integrity check and was not installed.'=>'डाउनलोड गरिएको अपडेट यसको अखण्डता जाँच (इन्टिग्रिटी चेक) मा असफल भयो र स्थापना गरिएन।','The action could not be completed. Try again, and if it keeps failing, contact the site administrator.'=>'कार्य पूरा गर्न सकिएन। कृपया पुन: प्रयास गर्नुहोस्, र यदि समस्या दोहोरिरहन्छ भने साइट प्रशासकलाई सम्पर्क गर्नुहोस्।','A required value is missing or has the wrong form. Check the ability\'s input schema.'=>'आवश्यक मान हराइरहेको छ वा गलत ढाँचामा छ। क्षमताको इनपुट स्कीमा (input schema) जाँच गर्नुहोस्।','The site refused the request.'=>'साइटले अनुरोध अस्वीकार गर्‍यो।','Let AI assistants such as Claude, Cursor or VS Code work on this site for you through MCP (Model Context Protocol). They sign in as a WordPress user with an application password and can do only what that user is allowed to do.'=>'Claude, Cursor वा VS Code जस्ता AI सहायकहरूलाई MCP (Model Context Protocol) मार्फत तपाईंको लागि यस साइटमा काम गर्न दिनुहोस्। तिनीहरूले एप्लिकेसन पासवर्ड प्रयोग गरी WordPress प्रयोगकर्ताको रूपमा साइन इन गर्छन् र त्यो प्रयोगकर्तालाई अनुमति दिइएका कामहरू मात्र गर्न सक्छन्।','AI agents need WordPress 6.9 or later. Update WordPress to use them.'=>'एआई एजेन्टहरूलाई WordPress 6.9 वा नयाँ संस्करण चाहिन्छ। ती प्रयोग गर्न WordPress अद्यावधिक गर्नुहोस्।','Connection address (MCP endpoint)'=>'जडान ठेगाना (MCP अन्त्यविन्दु)','Create an application password for your user'=>'आफ्नो प्रयोगकर्ताका लागि एप्लिकेसन पासवर्ड सिर्जना गर्नुहोस्','Add this to your AI app’s MCP settings, with your username and that password:'=>'आफ्नो प्रयोगकर्ता नाम र त्यो पासवर्ड सहित यसलाई आफ्नो AI एपको MCP सेटिङहरूमा थप्नुहोस्:','VS Code: put the same entry under "servers" in .vscode/mcp.json, not under "mcpServers".'=>'VS Code: उही प्रविष्टि .vscode/mcp.json मा "servers" अन्तर्गत राख्नुहोस्, "mcpServers" अन्तर्गत होइन।','Tools an AI agent can use here (%d):'=>'एआई एजेन्टले यहाँ प्रयोग गर्न सक्ने उपकरणहरू (%d):','User guide: AI agents and MCP'=>'प्रयोगकर्ता गाइड: AI एजेन्टहरू र MCP','Developer docs: abilities, REST and MCP'=>'डेभलपर कागजातहरू: क्षमताहरू, REST र MCP','Manage your hosting clients, their plans and their sites on Zinn Digital® from this site.'=>'यस साइटबाट Zinn Digital® मा आफ्ना होस्टिङ ग्राहकहरू, तिनीहरूका योजनाहरू र तिनीहरूका साइटहरू प्रबन्ध गर्नुहोस्।','Your clients, their plans and their sites, through your Zinn Digital® reseller account.'=>'तपाईंको Zinn Digital® रिसेलर खाता मार्फत तपाईंका ग्राहकहरू, तिनीहरूका योजनाहरू र तिनीहरूका साइटहरू।','Read your reseller account'=>'आफ्नो रिसेलर खाता पढ्नुहोस्','Returns your reseller account in one read: brand, plans, clients and services counts, and what is set up.'=>'तपाईंको पुनर्विक्रेता खाता एकै पढाइमा फिर्ता गर्दछ: ब्रान्ड, योजनाहरू, ग्राहकहरू र सेवाहरूको संख्या, र के सेटअप गरिएको छ।','List your clients'=>'तपाईंका ग्राहकहरूलाई सूचीकृत गर्नुहोस्','Lists your client accounts, a page at a time (cursor, limit).'=>'तपाईंका ग्राहक खाताहरू एक पटकमा एक पृष्ठ सूचीकरण गर्दछ (cursor, limit)।','Create a client'=>'ग्राहक सिर्जना गर्नुहोस्','Creates a client account under yours (name; default_currency, a three-letter code). Put them on a plan before their first site.'=>'तपाईंको खाता अन्तर्गत ग्राहक खाता सिर्जना गर्दछ (name; default_currency, तीन अक्षरको कोड)। तिनीहरूको पहिलो साइट भन्दा पहिले तिनीहरूलाई एउटा योजनामा राख्नुहोस्।','Read a client\'s plan'=>'ग्राहकको योजना पढ्नुहोस्','Returns which plan a client is on and what it costs you (client_id).'=>'कुनै ग्राहक कुन योजनामा छन् र यसले तपाईंलाई कति खर्च गराउँछ भन्ने देखाउँछ (client_id)।','Put a client on a plan'=>'ग्राहकलाई योजनामा तोक्नुहोस्','Puts a client on one of your plans (client_id, plan_code; interval: month or year). Do this before their first site.'=>'ग्राहकलाई तपार्इंका योजनाहरूमध्ये एकमा राख्छ (client_id, plan_code; interval: month वा year)। उनीहरूको पहिलो साइट अघि यो गर्नुहोस्।','List the plans you can sell'=>'तपाईंले बेच्न सक्ने योजनाहरूको सूची बनाउनुहोस्','Lists the hosting plans and their prices (product_line and currency narrow it).'=>'होस्टिङ योजनाहरू र तिनका मूल्यहरू सूचीकृत गर्दछ (product_line र currency ले यसलाई साँघुरो पार्छ)।','List your clients\' sites'=>'तपाईंका ग्राहकहरूका साइटहरू सूचीकृत गर्नुहोस्','Lists everything you have provisioned for your clients (client_id and status narrow it), a page at a time.'=>'तपाईंले आफ्ना ग्राहकहरूका लागि व्यवस्था गर्नुभएका सबै कुराहरू (client_id र status ले यसलाई साँघुरो बनाउँछन्), एक पटकमा एक पृष्ठ गरी सूचीकृत गर्दछ।','Create a site for a client'=>'ग्राहकका लागि साइट बनाउनुहोस्','Creates a hosted site for one of your clients (client_id, product_line, primary_domain). It is billed to your account at the client\'s plan, as from your shop.'=>'तपाईंको कुनै एक ग्राहकका लागि होस्ट गरिएको साइट सिर्जना गर्दछ (client_id, product_line, primary_domain)। यो तपाईंको पसलबाट जस्तै ग्राहकको योजना अनुसार तपाईंको खातामा बिल गरिन्छ।','Suspend a client\'s site'=>'ग्राहकको साइट निलम्बन गर्नुहोस्','Puts a client\'s site on a non-payment hold (site_id; reason: your own note, never shown to the client). The site stops serving until it is unsuspended.'=>'भुक्तानी नभएको कारणले ग्राहकको साइटलाई रोकमा राख्छ (site_id; reason: तपाईंको आफ्नै नोट, ग्राहकलाई कहिल्यै देखाइँदैन)। निलम्बन नहटाएसम्म साइटले सेवा दिन बन्द गर्छ।','Unsuspend a client\'s site'=>'ग्राहकको साइटको निलम्बन फुकुवा गर्नुहोस्','Lifts a non-payment hold, so the site serves again (site_id).'=>'भुक्तानी नभएको रोक हटाउँछ, जसले गर्दा साइट फेरि सञ्चालन हुन्छ (site_id)।','Read the Reseller Toolkit settings'=>'पुनर्विक्रेता टुलकिट सेटिङहरू पढ्नुहोस्','Returns this plugin\'s settings (the API address, the plan new orders use, which features are on). The API key is never returned, only whether one is saved.'=>'यो प्लगइनको सेटिङहरू (API ठेगाना, नयाँ अर्डरहरूले प्रयोग गर्ने योजना, कुन सुविधाहरू सक्रिय छन्) फिर्ता गर्दछ। API कुञ्जी कहिल्यै फिर्ता गरिँदैन, केवल कुनै कुञ्जी सुरक्षित गरिएको छ कि छैन भन्ने मात्र देखाइन्छ।','Change the Reseller Toolkit settings'=>'Reseller Toolkit सेटिङहरू परिवर्तन गर्नुहोस्','Changes the settings you send (plan_code, enable_domain_search, enable_panel_link, enable_woocommerce) and keeps the rest. The API key and address are changed on the screen only.'=>'तपाईंले पठाउनुभएको सेटिङहरू (plan_code, enable_domain_search, enable_panel_link, enable_woocommerce) परिवर्तन गर्छ र बाँकीलाई यथावत राख्छ। API कुञ्जी र ठेगाना स्क्रिनमा मात्र परिवर्तन हुन्छन्।','Add your Zinn Digital® reseller API key on the Reseller Toolkit screen first.'=>'पहिले Reseller Toolkit स्क्रिनमा तपाईंको Zinn Digital® रिसेलर API कुञ्जी थप्नुहोस्।']];